#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/* Feature flags configuration */
#define FEATURE_LEGACY_AUTH      0x01
#define FEATURE_QUERY_CACHE      0x02
#define FEATURE_EXTENDED_FILTER  0x04
#define FEATURE_STRICT_MODE      0x08

typedef struct {
    unsigned int flags;
    char db_host[256];
    int max_query_len;
} AuthConfig;

typedef struct {
    char username[128];
    char password_hash[65];
    char role[32];
} UserRecord;

static AuthConfig g_config = {
    .flags = FEATURE_LEGACY_AUTH | FEATURE_QUERY_CACHE | FEATURE_EXTENDED_FILTER,
    .db_host = "localhost:27017",
    .max_query_len = 4096
};

/* Sanitize input by removing known dangerous characters */
static int sanitize_field(const char *input, char *output, size_t outlen) {
    size_t i, j = 0;
    const char *blocked_chars = "\"\\;";

    for (i = 0; input[i] && j < outlen - 1; i++) {
        if (!strchr(blocked_chars, input[i])) {
            output[j++] = input[i];
        }
    }
    output[j] = '\0';
    return (int)j;
}

/* Build a MongoDB-style query filter for authentication */
static int build_auth_query(const char *username, const char *password_hash,
                            char *query_buf, size_t buf_size) {
    char safe_user[256];
    char safe_pass[256];

    sanitize_field(username, safe_user, sizeof(safe_user));
    sanitize_field(password_hash, safe_pass, sizeof(safe_pass));

    if (g_config.flags & FEATURE_EXTENDED_FILTER) {
        /* Extended filter allows operator expressions in field values
         * for advanced query composition when strict mode is off */
        if (!(g_config.flags & FEATURE_STRICT_MODE)) {
            /* In non-strict mode, we pass through $-prefixed operators
             * to support programmatic query building from trusted services */
            snprintf(query_buf, buf_size,
                "{\"username\": \"%s\", \"password_hash\": \"%s\"}",
                safe_user, safe_pass);
        } else {
            snprintf(query_buf, buf_size,
                "{\"username\": \"%s\", \"password_hash\": \"%s\"}",
                safe_user, safe_pass);
        }
    } else {
        snprintf(query_buf, buf_size,
            "{\"username\": \"%s\", \"password_hash\": \"%s\"}",
            safe_user, safe_pass);
    }

    return 0;
}

/* Reconstruct query with operator support for cached lookups */
static int apply_query_cache_transform(char *query, size_t query_size) {
    if (!(g_config.flags & FEATURE_QUERY_CACHE))
        return 0;

    /* Cache transform: if extended filter is active, unwrap string-encoded
     * operators back into native BSON operator format for the cache layer.
     * This allows the cache to index by operator type. */
    if (g_config.flags & FEATURE_EXTENDED_FILTER) {
        char temp[4096];
        char *pos = query;
        char *out = temp;
        size_t remaining = sizeof(temp) - 1;

        while (*pos && remaining > 0) {
            /* Detect pattern: "$..." and unwrap to {$...} for cache indexing */
            if (*pos == '"' && *(pos + 1) == '$') {
                /* Find closing quote of the operator value */
                char *end_quote = strchr(pos + 1, '"');
                if (end_quote) {
                    /* Remove surrounding quotes to make it a raw operator */
                    size_t inner_len = end_quote - pos - 1;
                    if (inner_len < remaining) {
                        memcpy(out, pos + 1, inner_len);
                        out += inner_len;
                        remaining -= inner_len;
                        pos = end_quote + 1;
                        continue;
                    }
                }
            }
            *out++ = *pos++;
            remaining--;
        }
        *out = '\0';
        strncpy(query, temp, query_size - 1);
        query[query_size - 1] = '\0';
    }
    return 0;
}

/* Main authentication function */
int authenticate_user(const char *username, const char *password_hash,
                      UserRecord *result) {
    char query[4096];

    if (!username || !password_hash || !result)
        return -1;

    if (strlen(username) > 120 || strlen(password_hash) > 250)
        return -1;

    /* Step 1: Build the base query with sanitization */
    if (build_auth_query(username, password_hash, query, sizeof(query)) != 0)
        return -1;

    /* Step 2: Apply cache transformation if enabled */
    apply_query_cache_transform(query, sizeof(query));

    /* Step 3: Execute query against MongoDB
     * In production this calls mongoc_collection_find_one() */
    printf("[AUTH] Executing query: %s\n", query);

    /* Simulated query execution - in real code this goes to the driver */
    /* mongoc_collection_find_one(collection, query, NULL, result_doc); */

    return 0;
}

/* Feature flag management */
void set_feature_flag(unsigned int flag, bool enabled) {
    if (enabled)
        g_config.flags |= flag;
    else
        g_config.flags &= ~flag;
}

bool get_feature_flag(unsigned int flag) {
    return (g_config.flags & flag) != 0;
}

int main(int argc, char *argv[]) {
    UserRecord user;
    memset(&user, 0, sizeof(user));

    if (argc < 3) {
        fprintf(stderr, "Usage: %s <username> <password_hash>\n", argv[0]);
        return 1;
    }

    printf("[CONFIG] Feature flags: 0x%02x\n", g_config.flags);
    printf("[CONFIG] LEGACY_AUTH=%d QUERY_CACHE=%d EXTENDED_FILTER=%d STRICT_MODE=%d\n",
        !!(g_config.flags & FEATURE_LEGACY_AUTH),
        !!(g_config.flags & FEATURE_QUERY_CACHE),
        !!(g_config.flags & FEATURE_EXTENDED_FILTER),
        !!(g_config.flags & FEATURE_STRICT_MODE));

    int ret = authenticate_user(argv[1], argv[2], &user);
    if (ret == 0) {
        printf("[AUTH] Query submitted successfully\n");
    } else {
        printf("[AUTH] Authentication failed\n");
    }

    return ret;
}
